import yaml, sys, glob, os

for root in ["30_Library","20_Thinking","01_journals","10_System","00_Inbox"]:
    for path in glob.glob(f"{root}/**/*.md", recursive=True):
        try:
            with open(path, encoding="utf-8") as f:
                content = f.read()
        except Exception:
            continue
        if not content.startswith("---"):
            continue
        try:
            end = content.index("\n---", 3)
        except ValueError:
            continue
        fm_text = content[3:end]
        try:
            fm = yaml.safe_load(fm_text)
        except Exception as e:
            print(f"YAML ERROR: {path}: {e}")
            continue
        if not isinstance(fm, dict):
            continue
        t = fm.get("type")
        if isinstance(t, list):
            print(f"LIST TYPE: {path}: {t}")
EOF
