python3 - << 'EOF'
claim_files = set(l.strip() for l in open("/tmp/claim_files.txt"))
lines = open("/tmp/full_audit.txt").read().split("\n")
current_file = None
results = {}
for line in lines:
    if line.startswith("  ✗ "):
        current_file = "./" + line[4:].strip()
        results[current_file] = []
    elif line.strip().startswith(("missing", "invalid")) and current_file:
        results[current_file].append(line.strip())

matched = {f: errs for f, errs in results.items() if f in claim_files}

from collections import Counter
sig_counter = Counter()
for f, errs in matched.items():
    # normalize signature: sorted tuple of error "kinds"
    kinds = []
    for e in errs:
        if e.startswith("missing required field"):
            kinds.append("REQUIRED:" + e.split("'")[1])
        elif e.startswith("missing schema field"):
            kinds.append("SCHEMA:" + e.split("'")[1])
        elif e.startswith("invalid type"):
            kinds.append("INVALIDTYPE")
        else:
            kinds.append("OTHER")
    sig_counter[tuple(sorted(kinds))] += 1

for sig, count in sig_counter.most_common():
    print(count, sig)
print("TOTAL:", len(matched))
EOF

